#!/usr/bin/env python3
"""reflect-construct-other-new-target.py <folder>: ONE CASE A FOLDER: Reflect.construct() of typed classes with another new.target: whose layout, whose prototype, what `instanceof` says, and which `super()` changes the answer."""
import os, sys

CASES = {'a-typed-class-made-for-another-new-target': {'main.ts': 'class L { a: number; constructor(a: number) { this.a = a; } }\nclass O { b?: string }\nclass T { a: number; constructor(a: number) { this.a = a; } }\nclass D extends T { constructor(a: number) { if (a) super(a); else super(0); } }\nconst o = Reflect.construct(L, [1], O), u: unknown = o;\nconsole.log(o instanceof O, u instanceof O, o instanceof L, u instanceof L, Object.getPrototypeOf(o) === O.prototype, O[Symbol.hasInstance](o), L[Symbol.hasInstance](o));\n'}, 'every-new-target': {'main.ts': 'const say = (f: () => unknown): string => { try { return String(f()); } catch (e) { return "THROWS " + (e as Error).name + ": " + (e as Error).message.slice(0, 60); } };\nclass A { x = 1; who: string; constructor() { this.who = new.target.name; } hi(): string { return "A.hi"; } }\nclass B { y = 2; hi(): string { return "B.hi"; } }\nclass SubA extends A { z = 3; override hi(): string { return "SubA.hi"; } }\nfunction F(this: any) {} F.prototype.hi = function () { return "F.hi"; };\nfunction Sub5(this: any): any { return Reflect.construct(A, [], Sub5); } Object.setPrototypeOf(Sub5.prototype, A.prototype); Object.setPrototypeOf(Sub5, A); Sub5.prototype.hi = function () { return "Sub5.hi"; };\nconst tell = (o: any, T: any): string => [o instanceof T, o instanceof A, Object.getPrototypeOf(o) === T.prototype, o.hi?.(), o.who, JSON.stringify(o)].join(" ");\nconsole.log("another typed class:", say(() => tell(Reflect.construct(A, [], B), B)));\nconsole.log("a plain function:", say(() => tell(Reflect.construct(A, [], F), F)));\nconsole.log("Object:", say(() => tell(Reflect.construct(A, [], Object), Object)));\nconsole.log("its own subclass:", say(() => tell(Reflect.construct(A, [], SubA), SubA)));\nconsole.log("itself:", say(() => tell(Reflect.construct(A, [], A), A)));\nconsole.log("an ES5 subclass:", say(() => tell(new (Sub5 as any)(), Sub5)));\nconsole.log("a bound function:", say(() => tell(Reflect.construct(A, [], F.bind(null)), F)));\nconsole.log("a proxy:", say(() => { const log: string[] = []; const P = new Proxy(F, { get(t, k, r) { log.push(String(k)); return Reflect.get(t, k, r); } }); return tell(Reflect.construct(A, [], P), F) + " " + log.join(); }));\nconsole.log("a prototype that is no object:", say(() => { function G(this: any) {} G.prototype = 5 as any; return Object.getPrototypeOf(Reflect.construct(A, [], G)) === Object.prototype; }));\nconsole.log("the subclass by the base\'s new.target:", say(() => tell(Reflect.construct(SubA, [], A), A)));\nconsole.log("an arrow:", say(() => Reflect.construct(A, [], (() => 1) as any)));\nfor (let i = 0; i < 300; i++) Reflect.construct(A, [], B); console.log("hot:", say(() => tell(Reflect.construct(A, [], B), B)));\n'}, 'which-super-lifts-the-guard': {'main.ts': 'const say = (f: () => unknown): string => { try { return String(f()); } catch (e) { return "THROWS " + (e as Error).name + " " + (e as Error).message.slice(0, 50); } };\nclass L { a: number; constructor(a: number) { this.a = a; } hi(): string { return "L.hi"; } }\nclass O { b?: string; hi(): string { return "O.hi"; } }\nfunction F(this: any) {} F.prototype.hi = () => "F.hi";\nclass T { a: number; constructor(a: number) { this.a = a; } }\nclass D extends T { constructor(a: number) { if (a) super(a); else super(0); } }\nconst what = (o: any): string => { const p = Object.getPrototypeOf(o); return [p === L.prototype ? "L.prototype" : p === O.prototype ? "O.prototype" : p === F.prototype ? "F.prototype" : p === Object.prototype ? "Object.prototype" : p === null ? "null" : "another: " + Object.getOwnPropertyNames(p).join("+"), typeof o.hi === "function" ? o.hi() : "no hi", o.constructor?.name, JSON.stringify(o), Object.keys(o).join()].join(" . "); };\nconsole.log("L by O:", say(() => what(Reflect.construct(L, [1], O))));\nconsole.log("L by F:", say(() => what(Reflect.construct(L, [1], F))));\nconsole.log("L by Object:", say(() => what(Reflect.construct(L, [1], Object))));\nconsole.log("L by L:", say(() => what(Reflect.construct(L, [1], L))));\nconsole.log("new L:", say(() => what(new L(1))));\nconsole.log("O by L:", say(() => what(Reflect.construct(O, [], L))));\nconsole.log("T by D:", say(() => what(Reflect.construct(T, [1], D))), "| D by T:", say(() => what(Reflect.construct(D, [1], T))));\n'}}

for case, files in CASES.items():
    for name, text in files.items():
        path = os.path.join(sys.argv[1], case, name)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        open(path, "w").write(text)
